def png(w: int, h: int, seed: int, text: str) -> bytes:
    digest = hashlib.sha256(f'{seed}|{w}x{h}|{text}'.encode()).digest()
    row = b'\x00' + digest[:3] * 4
    raw = row * 4

    def chunk(t, d):
        return struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t + d) & 4294967295)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', 4, 4, 8, 2, 0, 0, 0)) + chunk(b'tEXt', f'parameters\x00{text}, Seed: {seed}, Size: {w}x{h}'.encode('latin-1', 'replace')) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')
```

