def cmake_defs(backend: str, arch=None, rocm: Path | None=None, cuda_root: Path | None=None) -> list[str]:
    """CMake definitions for sd-cli on `backend`: arch = the CUDA compute capability ("86") or the gfx target."""
    defs = ['-DSD_BUILD_EXAMPLES=ON', '-DSD_WEBP=OFF', '-DSD_WEBM=OFF', '-DSD_BUILD_SHARED_LIBS=OFF', '-DGGML_NATIVE=ON']
    if backend == 'cuda':
        defs += ['-DSD_CUDA=ON'] + ([f'-DCMAKE_CUDA_ARCHITECTURES={arch}'] if arch else [])
        if cuda_root:
            defs += [f'-DCUDAToolkit_ROOT={cuda_root}']
    elif backend == 'hip':
        if not rocm:
            raise ValueError('the HIP build needs the ROCm folder')
        gfx = str(arch).split(':')[0]
        llvm = rocm / 'lib' / 'llvm' if (rocm / 'lib' / 'llvm' / 'bin').is_dir() else rocm / 'llvm'
        bitcode = next((p for p in (llvm / 'amdgcn' / 'bitcode', rocm / 'amdgcn' / 'bitcode') if p.is_dir()), llvm / 'amdgcn' / 'bitcode')
        defs += ['-DSD_HIPBLAS=ON', f'-DGPU_TARGETS={gfx}', f'-DAMDGPU_TARGETS={gfx}', f"-DCMAKE_C_COMPILER={llvm / 'bin' / 'clang'}", f"-DCMAKE_CXX_COMPILER={llvm / 'bin' / 'clang++'}", f"-DCMAKE_HIP_COMPILER={llvm / 'bin' / 'clang++'}", f"-DCMAKE_PREFIX_PATH={rocm};{rocm / 'lib' / 'rocm_sysdeps'};{llvm}", f'-DCMAKE_HIP_FLAGS=--rocm-path={rocm} --rocm-device-lib-path={bitcode}']
    elif backend == 'vulkan':
        defs += ['-DSD_VULKAN=ON']
    elif backend != 'cpu':
        raise ValueError(f'unknown backend {backend!r}')
    return defs
