    """(what, what to do) for a pick that goes beyond what was run: a warning, never a refusal.  `cards` are the usable cards of the run;
    `os_name` is sys.platform, `machine` sysinfo.machine().  Nothing for an unset or one-at-a-time pick."""
    out: list[tuple[str, str]] = []
    if n is None or int(n) <= 1:
        return out
    n = int(n)
    if n > MAX_CONVERSATIONS:
        out.append((f'--parallel {n} is more than the engine runs at once; it will use {MAX_CONVERSATIONS}.', f'Pick a number from 2 to {MAX_CONVERSATIONS}.'))
    os_name = (os_name or '').lower()
    machine = (machine or '').lower()
    mac = os_name == 'darwin' or vendor == 'apple' or any((str(c.get('vendor')) == 'apple' for c in cards or []))
    windows = os_name.startswith('win')
    uma_gpu = any((c.get('uma') or c.get('integrated') for c in cards or []))
    spark = os_name.startswith('linux') and machine in ('aarch64', 'arm64')
    if mac:
        out.append(('--parallel was not run on a Mac (Metal). The code adds no Metal kernel of its own, but nothing here has started it there.', 'If the engine stops at the start, launch without --parallel.'))
    elif windows:
        out.append(('--parallel was run on Linux only. The Windows engine builds with it; a Windows run has not been done.', 'If the engine stops at the start or an answer looks wrong, launch without --parallel.'))
    elif uma_gpu and (not spark):
        out.append(('--parallel was not run on a Ryzen AI Max (shared memory) PC. Every extra conversation takes memory the experts and the system also use.', 'If the engine stops or slows down, launch without --parallel.'))
    else:
        archs = {str(c.get('arch') or '') for c in cards or [] if c.get('arch')}
        odd = sorted((a for a in archs if a and (not a.startswith('gfx12'))))
        if str(vendor or '') == 'amd' and odd:
            out.append((f"--parallel was run on Radeon AI PRO R9700 cards (gfx1201); this PC has {', '.join(odd)}, which was not tried.", 'If the engine stops at the start, launch without --parallel.'))
    small = [c for c in cards or [] if 0 < float(c.get('vram_gb') or 0) < 24 and (not (c.get('uma') or c.get('integrated')))]
    if small and (not mac):
        c = small[0]
        gb = extra_gb(context)
        share = f' (about {gb:.2f} GB each at {_label(context)})' if gb is not None else ''
        out.append((f"{c.get('name') or 'A card'} has {float(c.get('vram_gb') or 0):.0f} GB; --parallel was run on cards with 32 GB and 48 GB. Each extra conversation takes graphics memory{share} that the experts would use, so fewer experts stay on the card and answers slow down; if the buffers do not fit, the engine runs fewer conversations and says so in its log.", 'A smaller --context leaves more room.'))
    return out
```

