reference.content:
```python
def install_progress(lines: list[str]) -> dict:
    """setup's progress from its output: the step, a download's percentage, a failure."""
    step, title, dl, err = (None, None, None, None)
    for i, line in enumerate(lines):
        m = re.search('=== Step (\\d+): (.+?) ===', line)
        if m:
            step, title, err, dl = (int(m.group(1)), m.group(2), None, None)
        m = re.match('\\s*(\\S.*?): +([\\d.]+) / ([\\d.]+) GB \\((\\d+)%\\)', line)
        if m:
            dl = {'file': m.group(1), 'done_gb': float(m.group(2)), 'total_gb': float(m.group(3)), 'percent': int(m.group(4))}
        if line.strip().startswith('[X]'):
            err = line.strip()[3:].strip()
            if i + 1 < len(lines) and lines[i + 1].startswith('       '):
                err += ' - ' + lines[i + 1].strip()
    out = {'step': f'{step}/7: {title}' if step else None}
    if dl:
        out['download'] = dl
    if err:
        out['error'] = err
    words = progress_words_for(step, lines, dl)
    if words:
        out['label'], out['phase'] = words
    return out
```

